function humanWork(id){const h=human(id),responsible=run&&humanForScenario(run.scenarioId)?.id===id,approval=id==='owner'&&!!run?.approval,deliveries=(run?.events||[]).filter(e=>e.type==='handoff'&&e.targetHumanId===id);if(approval)return {...h,status:'awaiting_approval',task:run.approval.title,action:'请审阅方案并明确批准或拒绝',result:'等待使用者操作',deliveries};if(responsible&&alive())return {...h,status:'waiting',task:run.title,action:'资料已提交，虚拟员工正在处理',result:'可查看真实执行记录',deliveries};if(responsible&&run?.artifacts?.length)return {...h,status:run.status==='completed'&&deliveries.some(e=>e.deliveryKind==='final_delivery')?'delivery':'files_available',task:run.title,action:run.status==='completed'&&deliveries.some(e=>e.deliveryKind==='final_delivery')?'查阅交付文件与证据':'查阅已保留文件与证据',result:run.status==='failed'?'任务失败，已保留过程证据':run.status==='cancelled'?'任务已取消，已保留过程证据':'等待使用者查阅与确认后续事项',deliveries};return {...h,status:'idle',task:'提供资料或接收交付',action:'选择本职能的办公任务',result:'由使用者操作',deliveries};}
function renderHuman(){const h=human(panel.id),state=humanWork(h.id),assigned=catalog.scenarios.filter(s=>humanForScenario(s.id)?.id===h.id),receives=(run?.events||[]).filter(e=>e.sourceHumanId===h.id||e.targetHumanId===h.id||e.actor==='human'&&h.id==='owner');return `${header(h.name,'真实员工（由你操作）')}<div class="human-profile">${humanAvatar(h.id)}<span><strong>${esc(h.role||h.name)}</strong><small>职能角色 · 资料、审批和查阅由使用者操作</small></span></div><div class="human-duty">${esc(HUMAN_DUTIES[h.id]||h.role||h.name)}</div><div class="human-todo"><small>当前待办</small><strong>${esc(state.task)}</strong><p>${esc(state.action)}</p><span>${esc(state.result)}</span></div>${h.id==='owner'&&run?.approval?'<button class="button button-primary human-action" data-open="approval">审阅待审批方案</button>':''}${run&&humanForScenario(run.scenarioId)?.id===h.id?`<div class="button-row"><button class="button" data-open="progress">查看任务进展</button>${run.artifacts?.length?'<button class="button button-primary" data-open="artifacts">查阅交付文件</button>':''}</div>`:''}${assigned.length?`<div class="office-section-label">提供资料并派发任务</div><div class="human-scenario-actions">${assigned.map(s=>`<button class="context-action" data-scenario="${esc(s.id)}" ${alive()?'disabled':''}>${icon(s.icon||'book')}<span>${esc(s.title)}<small>${esc(s.outputs.join(' · '))}</small></span>${icon('chevron')}</button>`).join('')}</div>`:''}${h.id==='owner'&&!run?.approval?'<div class="office-note">当前没有待审批事项。需要真人决定时，会在这里高亮请求。</div>':''}${receives.length?`<div class="office-section-label">真实交接记录</div>${receives.slice(-5).reverse().map(logMarkup).join('')}`:''}</div>`;}
function resultSummary(value,fallback){if(value&&typeof value==='object'&&typeof value.summary==='string')return value.summary;if(typeof value==='string'&&value.trimStart().startsWith('{')){try{const parsed=JSON.parse(value);if(typeof parsed?.summary==='string')return parsed.summary;}catch{const matched=value.match(/^\s*\{\s*"summary"\s*:\s*("(?:[^"\\]|\\.)*")/s);if(matched){try{return JSON.parse(matched[1]);}catch{}}if(typeof fallback?.summary==='string')return fallback.summary;}}return resultText(value);}
function investmentFindingText(value){return String(value??'').replace(/\b(?:issuer_claim|source_supported|corroborated|conflict|unverified)\b/g,status=>({issuer_claim:'项目方自述',source_supported:'有来源支持',corroborated:'多来源说法',conflict:'证据冲突',unverified:'待核实'}[status]));}
function cancelApprovalOpen(){if(pendingApprovalOpen?.timer)clearTimeout(pendingApprovalOpen.timer);pendingApprovalOpen=null;}
function revealApproval(runId,approvalId){if(run?.id!==runId||run?.approval?.id!==approvalId)return;cancelApprovalOpen();if(scene.focusHuman)scene.focusHuman('owner');else scene.focusNode('executive');openPanel('approval','owner');}
