function taskDraft(id){if(!drafts[id])drafts[id]=Object.fromEntries((scenario(id)?.fields||[]).filter(f=>f.type!=='file').map(f=>[f.name,f.defaultValue??'']));return drafts[id];}
function setInputSource(id,source){inputSource[id]=source;const d=taskDraft(id),isExample=source==='example';d.example=isExample;d.isExample=isExample;}
function fileFormats(id,fieldName){if(id==='investment'&&fieldName==='financials')return ['json','csv'];return ({investment:['txt','csv','json'],finance:['csv','json','xlsx'],ddos:['json','csv','txt'],database:['json','csv'],delivery:['txt','json','csv']})[id]||['csv','json','txt','xlsx'];}
function uploadPending(id){return [...pendingUploads.keys()].some(key=>key.startsWith(id+':'));}
async function handleUpload(id,fieldName,file){
  const key=id+':'+fieldName,token=Symbol('upload');
  delete taskDraft(id)[fieldName];
  setInputSource(id,'user');
  pendingUploads.set(key,{token,name:file.name});
  renderPanel(true);
  let failure;
  try{const value=await readUpload(file,id,fieldName);if(pendingUploads.get(key)?.token===token)taskDraft(id)[fieldName]=value;}
  catch(error){if(pendingUploads.get(key)?.token===token)failure=error;}
  finally{if(pendingUploads.get(key)?.token===token){pendingUploads.delete(key);if(panel?.type==='task'&&panel.id===id)renderPanel(true);}}
  if(failure)throw failure;
}
function financeFormat(){return `<div class="finance-format"><button type="button" class="button" data-finance-template>${icon('download')}下载示例模板</button><details class="workflow-preview"><summary>数据格式 · 11 列月度数据</summary><p>金额单位：元。汇报年与上一年各 12 个月，月末现金与下月期初现金衔接。</p><dl>${[['year','年度'],['month','月份'],['revenue','营业收入'],['cost','营业成本'],['operating_expense','经营费用'],['other_income','其他收益'],['tax','税费'],['opening_cash','期初现金'],['cash_in','现金流入'],['cash_out','现金流出'],['closing_cash','期末现金']].map(([name,label])=>`<div><dt>${name}</dt><dd>${label}</dd></div>`).join('')}</dl><p>用于经营与现金收支汇报，不替代法定财务三表。</p></details></div>`;}
async function downloadFinanceTemplate(){const data=await api('/api/examples/finance'),csv=data.input?.data?.text;if(typeof csv!=='string'||!csv.trim())throw new Error('示例模板暂不可用，请稍后重试。');const blob=new Blob(['\uFEFF',csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='明确示例_年度财务月度数据模板.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('示例模板已下载，请替换为你的月度数据后上传。');}
function investmentFinancialFormat(){return `<div class="finance-format investment-financial-format"><button type="button" class="button" data-investment-template>${icon('download')}下载财务示例模板</button><details class="workflow-preview"><summary>财务字段说明 · 7 列</summary><p>模板内容为虚构教学数据。请替换为项目实际资料，期间按上传顺序排列；金额使用所选币种的原始金额，不填“万元”。</p><dl>${[['period','期间，必填且不重复'],['revenue','营业收入，必填'],['gross_profit','毛利'],['net_profit','净利润，可为负'],['cash','现金余额'],['monthly_burn','每月净现金消耗'],['debt','债务余额']].map(([name,label])=>`<div><dt>${name}</dt><dd>${label}</dd></div>`).join('')}</dl><p>其他指标缺失可留空，不补零；最近两期按上传顺序比较。数学核算不代表财务已审计。</p></details></div>`;}
async function downloadInvestmentTemplate(){const result=await api('/api/examples/investment'),file=result.input?.financials,text=file?.text;if(typeof text!=='string'||!text.trim())throw new Error('投资财务示例模板暂不可用，请稍后重试。');const ext=/\.csv$/i.test(file.name||'')?'csv':'json',mime=ext==='csv'?'text/csv':'application/json',blob=new Blob([ext==='csv'?'\uFEFF':'',text],{type:mime+';charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='明确示例_虚构项目_财务模板.'+ext;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('已下载虚构示例模板，请替换为实际资料后上传。');}
function fieldMarkup(field,value,scenarioId){const formats=fileFormats(scenarioId,field.name),reading=pendingUploads.get(scenarioId+':'+field.name);const attrs=`name="${esc(field.name)}" ${busy?'disabled':''} ${field.required&&!(field.type==='file'&&value)?'required':''}`;let control;if(field.type==='textarea')control=`<textarea class="field-input" ${attrs} rows="${field.name==='requirements'?4:3}" placeholder="${esc(field.placeholder||'')}">${esc(value??'')}</textarea>`;else if(field.type==='select')control=`<select class="field-input" ${attrs}>${(field.options||[]).map(o=>{const v=typeof o==='object'?o.value:o,label=typeof o==='object'?o.label:o;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(label)}</option>`;}).join('')}</select>`;else if(field.type==='file')control=`<div class="file-upload"><input ${attrs} type="file" accept="${formats.map(ext=>'.'+ext).join(',')}" aria-label="${esc(field.label)}" ${value?'data-has-file="true"':''}><div class="file-value" data-file-value="${esc(field.name)}">${reading?`${icon('clock')}<span>${esc(reading.name)} · 正在读取</span>`:value?`${icon('check')}<span>${esc(value.name||'已载入示例资料')}</span><button type="button" class="button button-text" data-clear-file="${esc(field.name)}">移除</button>`:`${icon('download')}<span>${esc(field.placeholder||'上传 CSV / JSON / TXT / XLSX')}</span>`}</div></div>`;else control=`<input class="field-input" type="${field.type==='number'?'number':'text'}" ${attrs} value="${esc(value??'')}" placeholder="${esc(field.placeholder||'')}" ${field.type==='number'?'step="any"':''}>`;return `<label class="office-field"><span class="field-label">${esc(field.label)}${field.required?'<i>必填</i>':''}</span>${control}</label>`;}
function renderTask(){const s=scenario(panel.id);if(!s)return empty('任务目录未加载');const d=taskDraft(s.id),source=inputSource[s.id];return `${header(s.title,s.room)}<div class="human-input-owner"><button type="button" data-human="${esc(humanForScenario(s.id)?.id||'owner')}">${humanAvatar(humanForScenario(s.id)?.id||'owner')}${esc(humanForScenario(s.id)?.name||'你')}</button><span>提供资料 → 虚拟员工小队</span></div><form id="task-form" data-scenario-id="${esc(s.id)}"><div class="input-source ${source==='example'?'example':''}"><span>${source==='example'?`已载入示例：${esc(s.exampleLabel)}`:'使用你提供的资料与需求'}</span><button type="button" class="button" data-example="${esc(s.id)}" ${busy||uploadPending(s.id)?'disabled':''}>${icon('book')}使用示例</button></div><div class="config-form">${s.fields.map(f=>fieldMarkup(f,d[f.name],s.id)+(s.id==='finance'&&f.name==='data'?financeFormat():'')+(s.id==='investment'&&f.name==='financials'?investmentFinancialFormat():'')+(s.id==='investment'&&f.type==='file'?`<div class="upload-hint">${f.name==='financials'?'UTF-8 JSON / CSV · 最多 240,000 字符':'UTF-8 TXT / JSON / CSV · 正文与补充资料合计最多 24,000 字符'}</div>`:'')).join('')}</div><div class="office-section-label">执行小队 · ${s.agents.length} 位 虚拟员工</div><div class="related-agents">${s.agents.map(agentChip).join('')}</div><details class="workflow-preview"><summary>查看分工与交接</summary>${s.tasks.map(t=>`<div><span>${esc(agent(t.agentId).name)}</span><strong>${esc(t.title)}</strong><small>${t.dependencies.length?`等待 ${t.dependencies.map(id=>s.tasks.find(x=>x.id===id)?.title||id).map(esc).join('、')}`:'收到资料即可开始'}</small></div>`).join('')}</details><div id="task-error" hidden></div>${!health.provider?.ready?errorBox('模型尚未连接，先检查连接后再派工。'):''}<div class="form-actions"><button type="button" class="button" data-open="tasks">更换任务</button><button type="submit" class="button button-primary" ${busy||uploadPending(s.id)||alive()||!health.provider?.ready?'disabled':''}>${icon('play')}${busy?'正在创建任务':uploadPending(s.id)?'正在读取文件':'确认资料，一键派工'}</button></div></form></div>`;}
function renderEmployees(){return `${header('办公室员工','虚拟员工由模型执行 · 真实员工由你操作')}<div class="office-section-label">虚拟员工 <small>独立职责与工具权限</small></div><div class="office-employees">${catalog.agents.map(a=>`<button class="office-employee" data-agent="${esc(a.id)}">${portrait(a.id)}<span><strong>${esc(a.name)} <b class="ai-tag">虚拟</b></strong><small>${esc(a.role)}</small><em>${config(a.id).tools.map(t=>TOOLS[t]||t).map(esc).join(' · ')}</em></span>${icon('chevron')}</button>`).join('')}</div><div class="office-section-label human-section-label">真实员工（由你操作）</div><div class="office-employees real-employees">${HUMAN_EMPLOYEES.map(h=>{const work=humanWork(h.id);return `<button class="office-employee real-employee" data-human="${esc(h.id)}">${humanAvatar(h.id)}<span><strong>${esc(h.name)} <b class="real-tag">真实</b></strong><small>${esc(HUMAN_DUTIES[h.id]||h.role||h.name)}</small><em>${esc(work.status==='awaiting_approval'?'需要你审批':work.action)}</em></span>${icon('chevron')}</button>`;}).join('')}</div></div>`;}
function renderAgent(){const a=agent(panel.id),saved=config(a.id),current=run?.agents.find(x=>x.id===a.id),c=alive()&&current?{...saved,instructions:current.instructions??saved.instructions,tools:current.tools||saved.tools}:saved,workTools=current?.tools||c.tools,tasks=run?.tasks.filter(t=>t.agentId===a.id)||[],events=run?.events.filter(e=>e.agentId===a.id||e.targetAgentId===a.id)||[],tab=panel.tab||'work';let html=`${header(`${a.name} · ${a.role}`,'虚拟员工 / 独立上下文 / 受控工具')}<div class="popover-tabs"><button class="popover-tab ${tab==='work'?'active':''}" data-agent-tab="work">任务与行动</button><button class="popover-tab ${tab==='config'?'active':''}" data-agent-tab="config">配置员工</button><button class="popover-tab ${tab==='handoff'?'active':''}" data-agent-tab="handoff">证据交接</button></div>`;if(tab==='config'){html+=`<form id="agent-form" data-agent-id="${esc(a.id)}"><label class="office-field"><span class="field-label">职责指令</span><textarea class="field-input" name="instructions" rows="6" maxlength="1800" required ${alive()?'disabled':''}>${esc(c.instructions)}</textarea></label><div class="office-section-label">允许调用的工具</div><div class="tool-options">${a.tools.map(t=>`<label class="tool-option"><input type="checkbox" name="tools" value="${esc(t)}" ${c.tools.includes(t)?'checked':''} ${alive()?'disabled':''}><span><strong>${esc(TOOLS[t]||t)}</strong><small>${esc(t)}</small></span></label>`).join('')}</div><div class="office-note">${alive()?'本次执行已锁定配置。任务结束后可修改，下次派工生效。':'职责会发给真实模型；工具权限由服务端校验。'}</div><div id="agent-error" hidden></div><div class="form-actions"><button class="button button-primary" type="submit" ${alive()?'disabled':''}>${icon('check')}保存员工配置</button></div></form>`;}else if(tab==='handoff'){const handoffs=events.filter(e=>e.type==='handoff');html+=handoffs.length?handoffs.map(logMarkup).join(''):empty('完成上游任务后，证据会交给依赖该结果的同事。');}else{html+=`<div class="skill-tags">${workTools.map(t=>`<span class="skill-tag">${esc(TOOLS[t]||t)}</span>`).join('')}</div><div class="agent-work"><div class="work-label">任务</div><p class="work-text strong">${esc(current?.task||c.instructions)}</p></div><div class="agent-work"><div class="work-label">行动</div><p class="work-text">${esc(resultSummary(current?.action)||'等待派工')}</p></div><div class="agent-work"><div class="work-label">结果</div><p class="work-result">${esc(short(resultSummary(current?.result)||'尚未产出本次任务结果',1600))}</p></div>${tasks.length?`<div class="office-section-label">负责的任务</div>${tasks.map(taskMarkup).join('')}`:''}<div class="button-row"><button class="button" data-agent-tab="config">${icon('wrench')}修改职责与工具</button></div>`;}return html+'</div>';}
function taskMarkup(task){const latestTool=task.toolResults?.at(-1)?.result,summary=resultSummary(task.result,latestTool);return `<article class="office-task ${esc(task.status)}"><div><b>${esc(task.title)}</b><span>${esc(STATUS[task.status]||task.status)}</span></div><small>${esc(agent(task.agentId).name)} · 虚拟员工${task.dependencies?.length?` · ${task.dependencies.length} 项上游依赖`:''}</small>${task.action?`<p><em>行动</em>${esc(short(resultSummary(task.action),500))}</p>`:''}${task.result?`<p><em>结果</em>${esc(short(summary,900))}</p>`:''}${!task.output&&summary!==resultText(task.result)?evidenceMarkup(latestTool||task.result,'task-result-'+task.id,'查看工具返回证据'):''}${task.output?`<details class="evidence" data-evidence-key="task-${esc(task.id)}"><summary>查看员工交付</summary><pre>${esc(short(resultText(task.output),14000))}</pre></details>`:''}</article>`;}
function renderProgress(){if(!run)return `${header('任务进展')}${empty('派发任务后，实际执行进度会显示在这里。')}</div>`;const models=run.events.filter(e=>e.type==='model'&&e.step).length,tools=run.tasks.reduce((sum,t)=>sum+(Number(t.toolCalls)||0),0);return `${header(run.title,`${STATUS[run.status]} · ${run.model||run.provider||'真实模型'}`)}<div class="office-run-stats"><span><b>${run.tasks.filter(t=>t.status==='done').length}/${run.tasks.length}</b><small>已交付任务</small></span><span><b>${models}</b><small>模型决策</small></span><span><b>${tools}</b><small>工具调用</small></span><span><b>${fmtTime(run.elapsedSeconds)}</b><small>实际执行耗时</small></span></div>${run.error?errorBox(typeof run.error==='string'?run.error:run.error.message||JSON.stringify(run.error)):''}${run.summary?`<div class="office-summary">${esc(resultText(run.summary))}</div>`:''}${run.tasks.map(taskMarkup).join('')}<div class="button-row">${run.approval?`<button class="button button-primary" data-open="approval">需要你的审批</button>`:''}${TERMINAL.has(run.status)?`<button class="button" data-action="retry">${icon('reset')}重新执行</button><button class="button button-primary" data-open="artifacts">${icon('download')}查看实际产物</button>`:`<button class="button button-danger" data-action="cancel">取消任务</button>`}</div></div>`;}
function renderLogs(){const events=run?.events||[];return `${header('协作记录',run?`${run.title} · ${events.length} 条实际事件`:'模型、工具、交接与审批')}<div class="office-log-list">${events.length?events.slice().reverse().map(logMarkup).join(''):empty('尚无执行记录。')}</div></div>`;}
function renderArtifacts(){const files=run?.artifacts||[];return `${header('任务产物',run?`${run.title} · ${STATUS[run.status]}`:'下载实际生成的文件')}${files.length?files.map(artifactMarkup).join(''):empty(alive()?'员工执行后会在此交付文件。':'尚无文件产物。')} ${run?.status==='failed'?errorBox('任务执行失败，已经生成的证据保留在这里，可重试。'):''}${run?`<div class="button-row"><button class="button" data-open="progress">查看任务与验收</button></div>`:''}</div>`;}
function approvalContext(){const event=run?.events?.findLast(e=>e.type==='approval'&&e.agentId),requesterId=run?.approval?.agentId||event?.agentId,task=run?.tasks.find(t=>t.status==='running'&&(!requesterId||t.agentId===requesterId));return {requester:agent(requesterId||task?.agentId||'zhang'),task};}
function approvalPlan(a){const d=a.details||{};if(a.kind==='investment')return `<div class="approval-investment-summary">${esc(d.summary||a.description)}</div><div class="approval-investment-grid"><section><h3>关键发现</h3><ul>${(d.keyFindings||[]).map(v=>`<li>${esc(investmentFindingText(v))}</li>`).join('')||'<li>以已登记的证据与决策简报为准。</li>'}</ul></section><section class="critical"><h3>仍需补齐</h3><ul>${(d.criticalGaps||[]).map(v=>`<li>${esc(v)}</li>`).join('')||'<li>没有新增列明的资料缺口；不代表已作投资承诺。</li>'}</ul></section></div><div class="approval-investment-scope"><strong>决策范围</strong><p>${esc(d.environment||'仅记录后续研究决策，不签约、不下单、不打款。')}</p></div>`;const ips=Array.isArray(d.blockedIps)?d.blockedIps:[];return `<div class="approval-facts"><div><span>拟执行</span><strong>${ips.length?`封禁 ${ips.length} 个已识别来源`:'不增加 IP 封禁'}</strong>${ips.length?`<p class="approval-ip-list">${ips.map(ip=>`<code>${esc(ip)}</code>`).join('')}</p>`:''}</div><div><span>限速规则</span><strong>${d.rateLimit!=null?`每个来源 ${esc(d.windowSeconds||60)} 秒内允许 ${esc(d.rateLimit)} 次请求`:'本方案不启用额外限速'}</strong></div><div class="full"><span>影响范围</span><p>${esc(d.environment||'仅执行本次请求中列出的变更，范围以方案证据为准。')}</p></div><div class="full"><span>方案依据与风险</span><p>${esc(d.reason||a.description)}</p></div></div>`;}
function syncApprovalFocus(){const pending=!!run?.approval;$('#lab').classList.toggle('needs-approval',pending);$('#approval-backdrop').hidden=!(pending&&panel?.type==='approval');const request=$('#approval-request');request.hidden=!pending;if(pending){const {requester}=approvalContext();request.innerHTML=`${icon('users')}<span><strong>需要你审批</strong><small>${esc(requester.name)}正在请求 · ${esc(run.approval.title)}</small></span>${icon('chevron')}`;}}
function renderApproval(){
  const a=run?.approval;if(!a)return `${header('真人审批')}${empty('当前没有待审批事项。')}</div>`;
  const {requester,task}=approvalContext(),investment=a.kind==='investment';
  return `<div class="popover-inner approval-dialog"><div class="approval-dialog-top"><span class="approval-eyebrow">${investment?'老板审阅 · 等待你的决定':'真人审批 · 等待你的决定'}</span><button class="button button-text" data-close aria-label="回到现场，稍后审批">回到现场 ${icon('close')}</button></div><div class="approval-dialog-layout"><section class="approval-owner"><div class="approval-person">${humanPortrait()}</div><h2>你</h2><span class="human-label">${investment?'老板 · 真人审批人':'真人负责人'}</span><p>${investment?'决定是否继续投入尽调资源。':'这一步需要你的授权。'}<br>虚拟员工不能代你批准。</p><div class="approval-from">${portrait(requester.id)}<span><strong>${esc(requester.name)} <b class="ai-tag">虚拟员工</b></strong><small>${esc(requester.role)}</small></span></div><div class="approval-task-name"><small>请求审批的任务</small><strong>${esc(task?.title||run.title)}</strong></div></section><section class="approval-decision"><h2>${esc(a.title)}</h2><p class="approval-description">${esc(a.description)}</p><div class="approval-review" tabindex="0" aria-label="审批方案和证据，可在区域内滚动">${approvalPlan(a)}${evidenceMarkup(a.details,a.id,'展开技术参数与原始证据')}</div><label class="office-field approval-comment"><span class="field-label">审批备注 <small>可选</small></span><textarea class="field-input" id="approval-note" rows="2" maxlength="500" placeholder="填写审批依据或调整要求"></textarea></label><div id="approval-error" hidden></div><div class="approval-choice"><button class="button approval-reject" data-approval="false" ${busy?'disabled':''}>${icon('close')}${investment?'暂缓项目':'拒绝本次方案'}</button><button class="button button-primary approval-confirm" data-approval="true" ${busy?'disabled':''}>${icon('check')}${investment?'继续尽调':'批准执行'}</button></div><p class="approval-next">${investment?'本次仅记录后续研究决策，不签约投资、不下单、不打款。':'批准后交由虚拟员工执行并独立验证；拒绝则不应用策略，保留提案与证据。'}</p></section></div></div>`;
}
function renderConnection(){const p=health.provider||{};return `${header('模型连接','办公室服务端运行 · 凭证仅保存在服务端')}<div class="provider-status ${p.ready?'ready':''}">${icon(p.ready?'check':'info')}<span><strong>${p.ready?'已连接真实模型':'模型未连接'}</strong><small>${esc(p.provider||'Codex')} · ${esc(p.model||'等待检测')}</small></span></div><p class="office-note">${esc(p.message||'检查本机模型登录状态。')}</p>${p.ready?'':'<p class="office-note">优先使用办公室主机已登录的 Codex；也可在服务端配置 OpenAI 或 Ollama。连接成功前不能派工。</p>'}<div id="connection-error" hidden></div><div class="button-row"><button class="button button-primary" data-action="check-provider" ${busy?'disabled':''}>${icon('reset')}${busy?'正在检查':'重新检查连接'}</button></div><div class="office-section-label">执行边界</div><div class="office-note">财务使用你提供的数据；采购从实时网页保留报价证据；DDoS 在隔离请求副本验证；数据库在任务工作区真实创建；对外采购、付款与发布由你决定。</div></div>`;}
function renderHistory(){return `${header('任务历史','输入、证据与产物保存在办公室主机')}<div class="office-history">${runs.length?runs.map(r=>`<button class="history-row" data-run="${esc(r.id)}"><span><strong>${esc(r.title)}</strong><small>${date(r.createdAt)} · ${r.artifacts?.length||0} 个文件</small></span><em class="status-${esc(r.status)}">${esc(STATUS[r.status])}</em>${icon('chevron')}</button>`).join(''):empty('尚无历史任务。')}</div></div>`;}
function renderNode(){const id=panel.id,s=scenario(NODE_SCENARIO[id]);const events=run?.events.filter(e=>run.tasks.find(t=>t.id===e.taskId)?.nodeId===id)||[];return `${header(NODE_NAMES[id]||id,'工作区动作')}${s?`<button class="context-action" data-scenario="${esc(s.id)}">${icon(s.icon)}<span>${esc(s.title)}<small>${esc(s.outputs.join(' · '))}</small></span>${icon('chevron')}</button>`:''}<div class="office-section-label">本次工作记录 · ${events.length}</div>${events.length?events.slice(-5).reverse().map(logMarkup).join(''):empty('该工作区尚未执行任务。')}<button class="button" data-open="tasks">查看全部办公任务</button></div>`;}
function renderMore(){return `${header('办公动作')}<div class="more-actions"><button class="button" data-open="history">${icon('clock')}任务历史</button><button class="button" data-open="connection">${icon('activity')}模型连接</button><button class="button" data-open="progress">${icon('layers')}任务分工</button><button class="button" data-action="refresh">${icon('reset')}刷新状态</button>${alive()?`<button class="button button-danger" data-action="cancel">${icon('close')}取消当前任务</button>`:''}</div><div class="human-identity">${icon('users')}<span><strong>真人负责人：你</strong><small>青绿 虚拟员工执行分析与工具；审批和业务决策由你完成。</small></span></div></div>`;}
function renderPanel(force=false){if(!panel)return;const frozen=panel.type==='task'||panel.type==='agent'&&panel.tab==='config'||panel.type==='approval';const sig=JSON.stringify([panel,frozen?'':run?.updatedAt,panel.type==='approval'?run?.approval?.id:null,panel.type==='approval'?run?.status:null,health.provider?.ready,health.provider?.message,busy,runs.length]);if(!force&&sig===panelSignature)return;panelSignature=sig;const scroll=$panel.scrollTop,opened=new Set([...$panel.querySelectorAll('details[data-evidence-key][open]')].map(d=>d.dataset.evidenceKey));const renderers={tasks:renderTasks,task:renderTask,employees:renderEmployees,human:renderHuman,agent:renderAgent,progress:renderProgress,logs:renderLogs,artifacts:renderArtifacts,approval:renderApproval,connection:renderConnection,history:renderHistory,node:renderNode,more:renderMore};$content.innerHTML=(renderers[panel.type]||renderTasks)();$panel.hidden=false;$panel.className=`scene-popover glass office-panel ${['task','progress','logs','artifacts','history'].includes(panel.type)?'wide':''} ${panel.type==='approval'?'approval':''}`;$panel.querySelectorAll('details[data-evidence-key]').forEach(d=>{if(opened.has(d.dataset.evidenceKey))d.open=true;});$panel.setAttribute('role',panel.type==='approval'?'dialog':'complementary');$panel.setAttribute('aria-modal',String(panel.type==='approval'));$panel.setAttribute('aria-label',panel.type==='approval'?'真人负责人审批对话框':'场景操作面板');$panel.scrollTop=scroll;syncApprovalFocus();positionOverlays();}
function updateScene(){const agents=run?.agents?.length?run.agents:catalog.agents.map(a=>({...a,configured:true,selected:true,status:'idle'}));scene.update({runId:run?.id||null,runStatus:run?.status||'idle',animateEvents:sceneAnimateEvents,nodes:run?.nodes||{},agents,humans:HUMAN_EMPLOYEES.map(h=>humanWork(h.id)),logs:(run?.events||[]).filter(e=>!sceneBaselineEvents.has(e.id)),humanApproval:!!run?.approval});}
function render(){renderHud();renderDock();renderPanel();updateScene();renderNotices();}
function positionOverlays(){if(!$('#lab'))return;const bounds=$('#lab').getBoundingClientRect(),origin=$scene.getBoundingClientRect(),w=bounds.width,h=bounds.height;if(panel&&!$panel.hidden){const b=$panel.getBoundingClientRect(),anchor=panel.type==='agent'?scene.getAgentAnchor(panel.id):panel.type==='human'?(scene.getHumanAnchor?.(panel.id)||null):panel.type==='node'?scene.getNodeAnchor(panel.id):null;let left=(w-b.width)/2,top=(h-b.height)/2-8;if(anchor&&w>850){const x=anchor.x+origin.left-bounds.left,y=anchor.y+origin.top-bounds.top;left=x+40+b.width<w-16?x+40:x-b.width-40;top=y-100;}$panel.style.left=`${Math.max(12,Math.min(w-b.width-12,left))}px`;$panel.style.top=`${Math.max(12,Math.min(h-b.height-88,top))}px`;}
const occupied=[];for(const [id]of notices){const el=noticeLayer.querySelector(`[data-notice="${id}"]`),p=scene.getAgentAnchor(id);if(!el||!p)continue;const ew=el.offsetWidth,eh=el.offsetHeight;let x=Math.max(12,Math.min(w-ew-12,p.x+origin.left-bounds.left-ew/2)),y=Math.max(104,Math.min(h-eh-94,p.y+origin.top-bounds.top-eh-35));for(const b of occupied)if(x<b.x+b.w+8&&x+ew>b.x-8&&y<b.y+b.h+8&&y+eh>b.y-8){y=Math.min(h-eh-94,b.y+b.h+10);if(y<b.y+b.h&&w>650)x=Math.max(12,Math.min(w-ew-12,b.x+ew+12));}el.style.left=`${x}px`;el.style.top=`${y}px`;occupied.push({x,y,w:ew,h:eh});}}
function receive(next,{initial=false}={}){if(!next)return;const approvalResolved=panel?.type==='approval'&&run?.approval&&!next.approval,wasAwaiting=!!run?.approval;const changed=run?.id!==next.id;if(changed){cancelApprovalOpen();sceneBaselineEvents.clear();seenEvents.clear();notices.clear();noticeQueue.splice(0);lastApprovalId=null;}if(initial){for(const e of next.events||[])sceneBaselineEvents.add(e.id);}sceneAnimateEvents=!initial;run=next;if(!next.approval)cancelApprovalOpen();runs=[next,...runs.filter(r=>r.id!==next.id)].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));for(const e of next.events||[]){if(seenEvents.has(e.id))continue;seenEvents.add(e.id);if(!initial&&e.type==='result'&&e.agentId){const task=next.tasks.find(t=>t.id===e.taskId);noticeQueue.push({id:e.id,agentId:e.agentId,task:task?.title||agent(e.agentId).role,action:task?.action||e.tool&&TOOLS[e.tool]||'已执行工具与分析',result:e.text||resultText(task?.result),remaining:10000});}}
if(wasAwaiting&&!next.approval)scene.resetView();if(approvalResolved)openPanel('progress');if(next.approval&&next.approval.id!==lastApprovalId){lastApprovalId=next.approval.id;if(initial)revealApproval(next.id,next.approval.id);else scheduleApprovalOpen();}if(TERMINAL.has(next.status)){stream?.close();stream=null;clearTimeout(reconnectTimer);connectionState='closed';if(changed||!initial)toast(next.status==='completed'?'任务已交付，可在「产物」下载文件':next.status==='failed'?'任务失败，证据已保留，可查看原因后重试':'任务已取消');}render();}
function subscribe(id){stream?.close();clearTimeout(reconnectTimer);connectionState='connecting';stream=new EventSource(`/api/runs/${encodeURIComponent(id)}/events`);stream.addEventListener('state',event=>{try{const data=JSON.parse(event.data);connectionState='live';receive(data.run);}catch(error){console.error('Invalid run state',error);}});stream.onopen=()=>{connectionState='live';renderHud();};stream.onerror=()=>{if(!alive())return;connectionState='reconnecting';renderHud();clearTimeout(reconnectTimer);reconnectTimer=setTimeout(async()=>{try{const data=await api(`/api/runs/${encodeURIComponent(id)}`);if(run?.id===id)receive(data.run);}catch{toast('暂时无法同步任务，连接恢复后会自动继续。');}},5000);};}
function showFieldError(id,error){const el=$(id);if(el){el.innerHTML=errorBox(error.message||String(error));el.hidden=false;el.scrollIntoView({block:'nearest'});}else toast(error.message||String(error));}
function captureTaskForm(){const form=$('#task-form');if(!form)return;const id=form.dataset.scenarioId,d=taskDraft(id);for(const f of scenario(id).fields){if(f.type==='file')continue;const control=form.elements.namedItem(f.name);if(control)d[f.name]=f.type==='number'&&control.value!==''?Number(control.value):control.value;}setInputSource(id,inputSource[id]==='example'?'example':'user');}
async function readUpload(file,scenarioId,fieldName){if(file.size===0)throw new Error('文件为空，请选择有内容的资料。');if(file.size>8*1024*1024)throw new Error('单个文件最大 8 MB，请精简资料后再上传。');const ext=file.name.split('.').pop().toLowerCase();const formats=fileFormats(scenarioId,fieldName);if(!formats.includes(ext))throw new Error('此任务支持 '+formats.map(t=>t.toUpperCase()).join(' / ')+' 文件。文本请使用 UTF-8 编码。');if(ext==='xlsx'){const buffer=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<buffer.length;i+=8192)binary+=String.fromCharCode(...buffer.subarray(i,i+8192));return {name:file.name,base64:btoa(binary)};}const text=await file.text();if(scenarioId==='investment'){const limit=fieldName==='financials'?240000:24000;if(text.length>limit)throw new Error('此项投资资料最多 '+limit+' 字符，请精简后上传。');}return {name:file.name,text};}
async function startTask(form){if(busy)return;captureTaskForm();const id=form.dataset.scenarioId;if(uploadPending(id))throw new Error('文件仍在读取，请完成后再派工。');const s=scenario(id),input={...taskDraft(id),example:inputSource[id]==='example',isExample:inputSource[id]==='example',_source:inputSource[id]==='example'?'example':'user'};for(const f of s.fields){const v=input[f.name];if(!f.required&&v==='')delete input[f.name];if(f.required&&(v==null||v===''||f.type==='file'&&!v))throw new Error(`请提供${f.label}，也可以明确选择「使用示例」。`);}busy=true;renderPanel(true);try{const data=await api('/api/runs','POST',{scenarioId:id,input,agentConfigs:catalog.agents.map(a=>({id:a.id,instructions:config(a.id).instructions,tools:config(a.id).tools}))});closePanel();receive(data.run);subscribe(data.run.id);toast('任务已派发，虚拟员工开始执行。');}finally{busy=false;render();}}
async function action(name){if(busy)return;if(name==='check-provider'){busy=true;renderPanel(true);try{const data=await api('/api/provider/check','POST',{});health.provider=data.provider;toast(data.provider.ready?'模型连接成功':data.provider.message||'模型尚未连接');}finally{busy=false;render();}}else if(name==='refresh'){const [h,r]=await Promise.all([api('/api/health'),api('/api/runs')]);health=h;runs=r.runs||[];if(run){const found=runs.find(x=>x.id===run.id);if(found)receive(found,{initial:true});}render();toast('状态已更新');}else if(name==='cancel'){if(!alive())return;busy=true;try{const data=await api(`/api/runs/${encodeURIComponent(run.id)}/cancel`,'POST',{});receive(data.run);openPanel('progress');}finally{busy=false;render();}}else if(name==='retry'){if(!run||alive())return;busy=true;try{const data=await api(`/api/runs/${encodeURIComponent(run.id)}/retry`,'POST',{});closePanel();receive(data.run);subscribe(data.run.id);}finally{busy=false;render();}}}
document.addEventListener('click',async event=>{const button=event.target.closest('button,[data-open]');if(!button)return;try{if(button.hasAttribute('data-close'))return closePanel();if(button.dataset.open)return openPanel(button.dataset.open);if(button.dataset.human)return openPanel('human',button.dataset.human);if(button.dataset.agent)return openPanel('agent',button.dataset.agent,'work');if(button.dataset.agentTab){panel.tab=button.dataset.agentTab;return renderPanel(true);}if(button.dataset.scenario){if(alive())return toast('请先等待当前任务完成，或取消当前任务。');return openPanel('task',button.dataset.scenario);}if(button.hasAttribute('data-investment-template')){button.disabled=true;try{await downloadInvestmentTemplate();}finally{button.disabled=false;}return;}if(button.hasAttribute('data-finance-template')){button.disabled=true;try{await downloadFinanceTemplate();}finally{button.disabled=false;}return;}if(button.dataset.example){captureTaskForm();const id=button.dataset.example;busy=true;renderPanel(true);try{const data=await api(`/api/examples/${encodeURIComponent(id)}`);drafts[id]=data.input;setInputSource(id,'example');toast('已载入明确标记的示例资料，可修改后派工。');}finally{busy=false;renderPanel(true);}return;}if(button.dataset.clearFile){captureTaskForm();const id=panel.id;delete taskDraft(id)[button.dataset.clearFile];setInputSource(id,'user');return renderPanel(true);}if(button.dataset.action)return await action(button.dataset.action);if(button.dataset.approval){if(busy||!run?.approval)return;const note=$('#approval-note')?.value||'',approvalId=run.approval.id;busy=true;try{const data=await api(`/api/runs/${encodeURIComponent(run.id)}/approval`,'POST',{approved:button.dataset.approval==='true',note,approvalId});closePanel();receive(data.run);if(!TERMINAL.has(data.run.status))subscribe(data.run.id);}catch(error){showFieldError('#approval-error',error);}finally{busy=false;render();}return;}if(button.dataset.run){const data=await api(`/api/runs/${encodeURIComponent(button.dataset.run)}`);receive(data.run,{initial:true});if(!TERMINAL.has(data.run.status))subscribe(data.run.id);else{stream?.close();stream=null;}openPanel('progress');return;}if(button.dataset.dismissNotice){notices.delete(button.dataset.dismissNotice);renderNotices();return;}}catch(error){showFieldError(panel?.type==='connection'?'#connection-error':panel?.type==='task'?'#task-error':'#missing',error);}});
document.addEventListener('submit',async event=>{if(event.target.id==='task-form'){event.preventDefault();try{await startTask(event.target);}catch(error){showFieldError('#task-error',error);}}else if(event.target.id==='agent-form'){event.preventDefault();if(alive())return showFieldError('#agent-error',new Error('任务执行期间配置已锁定。'));const form=event.target,id=form.dataset.agentId,instructions=form.elements.instructions.value.trim(),tools=[...form.querySelectorAll('[name="tools"]:checked')].map(el=>el.value);if(!instructions)return showFieldError('#agent-error',new Error('请填写具体职责。'));if(!tools.length)return showFieldError('#agent-error',new Error('至少保留一个工具。'));configs[id]={instructions,tools};try{localStorage.setItem(CONFIG_KEY,JSON.stringify(configs));}catch{toast('配置已应用，但浏览器存储不可用。');}toast(`${agent(id).name}的职责与工具已保存，下次派工生效。`);panel.tab='work';renderPanel(true);}});
document.addEventListener('change',async event=>{const input=event.target;if(input.type==='file'&&input.closest('#task-form')){captureTaskForm();const id=panel.id;try{if(input.files[0]){await handleUpload(id,input.name,input.files[0]);}}catch(error){input.value='';showFieldError('#task-error',error);}}else if(input.closest('#task-form')){captureTaskForm();setInputSource(panel.id,inputSource[panel.id]==='example'?'example':'user');}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&panel)closePanel();});
$('#zoom-in').addEventListener('click',()=>scene.zoom(.15));$('#zoom-out').addEventListener('click',()=>scene.zoom(-.15));$('#zoom-fit').addEventListener('click',()=>{$scene.classList.toggle('overview');scene.resetView();});$('#topology-toggle').addEventListener('click',event=>{topology=!topology;scene.setTopology(topology);event.currentTarget.classList.toggle('active',topology);event.currentTarget.setAttribute('aria-pressed',String(topology));});
function renderNotices(){noticeLayer.hidden=!!panel;const capacity=innerWidth<720?1:2;while(notices.size>capacity){const [id,notice]=[...notices.entries()].at(-1);notices.delete(id);noticeQueue.unshift(notice);}while(notices.size<capacity&&noticeQueue.length){const index=noticeQueue.findIndex(n=>!notices.has(n.agentId));if(index<0)break;const next=noticeQueue.splice(index,1)[0];notices.set(next.agentId,next);}noticeLayer.innerHTML=[...notices.values()].map(n=>`<article class="employee-notice" data-notice="${esc(n.agentId)}"><div class="employee-notice-head"><button data-agent="${esc(n.agentId)}">${portrait(n.agentId)}<span><strong>${esc(agent(n.agentId).name)} <small>虚拟员工</small></strong><em>${esc(agent(n.agentId).role)}</em></span></button><button class="icon-button" data-dismiss-notice="${esc(n.agentId)}" aria-label="收起${esc(agent(n.agentId).name)}的行动提示">${icon('close')}</button></div><dl><div><dt>任务</dt><dd>${esc(n.task)}</dd></div><div><dt>行动</dt><dd>${esc(short(resultSummary(n.action),220))}</dd></div><div class="notice-result"><dt>结果</dt><dd>${esc(short(resultSummary(n.result),300))}</dd></div></dl></article>`).join('');positionOverlays();}
let noticeTick=performance.now();setInterval(()=>{const now=performance.now(),elapsed=now-noticeTick;noticeTick=now;if(panel)return;let changed=false;for(const [id,n]of notices){n.remaining-=elapsed;if(n.remaining<=0){notices.delete(id);changed=true;}}if(changed)renderNotices();},500);
window.addEventListener('resize',()=>{renderNotices();positionOverlays();});
async function boot(){renderHud();renderDock();try{const results=await Promise.allSettled([api('/api/catalog'),api('/api/health'),api('/api/runs')]);if(results[0].status!=='fulfilled')throw results[0].reason;catalog=results[0].value;try{const saved=JSON.parse(localStorage.getItem(CONFIG_KEY)||'{}');for(const a of catalog.agents){const c=saved[a.id];if(c&&typeof c.instructions==='string'&&Array.isArray(c.tools))configs[a.id]={instructions:c.instructions,tools:c.tools.filter(t=>a.tools.includes(t))};}}catch{}if(results[1].status==='fulfilled')health=results[1].value;else health.provider={ready:false,message:results[1].reason.message};if(results[2].status==='fulfilled')runs=results[2].value.runs||[];const current=runs.find(r=>!TERMINAL.has(r.status))||runs[0];if(current){receive(current,{initial:true});if(!TERMINAL.has(current.status))subscribe(current.id);}render();}catch(error){health.provider={ready:false,message:error.message};render();openPanel('connection');}}
boot();
